<?php
namespace App\Console\Commands;
use App\Domain\Identity\Enums\UserStatus;use App\Models\State;use App\Models\User;use App\Models\UserGeographicScope;use Illuminate\Console\Command;use Illuminate\Support\Facades\Hash;
class CreateSuperAdministrator extends Command{protected $signature='dms:create-super-admin';protected $description='Create the initial DMS super administrator';public function handle():int{$name=$this->ask('Officer name');$username=$this->ask('Username');$email=$this->ask('Email (optional)');$password=$this->secret('Password (minimum 12 characters)');if(strlen((string)$password)<12){$this->error('Password must be at least 12 characters.');return self::FAILURE;}if(User::where('username',$username)->exists()){$this->error('Username already exists.');return self::FAILURE;}$user=User::create(['username'=>$username,'name'=>$name,'email'=>$email?:null,'password'=>Hash::make($password),'status'=>UserStatus::Active,'password_changed_at'=>now(),'mfa_required'=>true]);$user->assignRole('Super Administrator');$state=State::where('code','AS')->first();if($state)UserGeographicScope::create(['user_id'=>$user->id,'scope_level'=>'STATE','state_id'=>$state->id,'assigned_by'=>$user->id,'assigned_at'=>now()]);$this->info('Super Administrator created. MFA enrollment must be completed when MFA is enabled.');return self::SUCCESS;}}
